        "**HUKUKİ DAYANAK** : İİK m.62, m.63, m.169; TMK m.6.\n\n"
        "**SONUÇ VE İSTEM**\n\n"
        "1. Ödeme emrine konu **borca, faize, ferilerine ve tüm takip işlemlerine itiraz "
