        "2. İtirazın dosyaya işlenerek alacaklıya tebliğine\n\n"
        "karar verilmesini saygıyla arz ve talep ederim. [Tarih]\n\n"
        "Borçlu Vekili\nAv. [Ad Soyad]\n[İmza]\n\n"
        "---\n\n"
        "> **Not**: İtiraz, ödeme emrinin tebliğinden itibaren **7 gün içinde** doğrudan icra "
