        "üstün yararı, velayetin anneye verilmesini gerektirmektedir.\n\n"
        "**HUKUKİ DAYANAK** : TMK m.183, m.337, m.349; HMK m.119 vd.\n\n"
        "**DELİLLER** : Önceki boşanma/velayet kararı, okul/sağlık raporları, sosyal inceleme "
