        "**VEKİLİ** : Av. [Ad Soyad] — [Baro / Sicil No] — [Adres]\n\n"
        "**DAVALI** : [Sigorta Şirketi Unvanı] — [Adres]\n\n"
        "**KONU** : Trafik kazası nedeniyle uğranılan ve eksik ödenen zararın bakiye kısmı "
        "olan 80.000,00 TL'nin davalı sigorta şirketinden tahsili talebidir.\n\n"
        "**HARCA ESAS DEĞER** : 80.000,00 TL\n\n"
        "**AÇIKLAMALAR**\n\n"
        "1. [Tarih] tarihinde meydana gelen trafik kazasında, davalı şirketçe trafik "
