        "[Esas/Karar No] sayılı ceza yargılaması ile sabittir (EK-1).\n\n"
        "2. Müvekkilim, kaza nedeniyle [yaralanma türü] yaralanmış; tedavi giderleri, geçici "
        "iş göremezlik ve sürekli iş göremezlik zararları için davalıya başvurmuş, davalı "
        "şirket [tarih] tarihinde yalnızca [ödenen miktar] TL ödeme yapmıştır (EK-2).\n\n"
        "3. Yaptırılan aktüer/bilirkişi hesabına göre müvekkilimin gerçek zararı ile davalı "
        "tarafından yapılan ödeme arasında **80.000,00 TL fark** bulunmaktadır (EK-3). Davalı, "
        "Karayolları Trafik Kanunu m.85 ve 5684 sayılı Sigortacılık Kanunu kapsamında bu "
        "farkı tazminle yükümlüdür.\n\n"
        "**HUKUKİ DAYANAK** : 2918 sayılı KTK m.85, m.90; TBK m.49, m.55; 5684 sayılı "
