        "bu nedenle müvekkilim kıdem ve ihbar tazminatına hak kazanmıştır (4857 m.17, "
        "1475 sayılı Kanun m.14).\n\n"
        "3. Müvekkilim, çalışması süresince düzenli olarak günlük mesai saatlerini aşan "
        "şekilde çalıştırılmış, hafta tatili ve yıllık izin haklarını kullandırılmadan "
        "çalışmaya devam etmiş; bu alacakları kendisine ödenmemiştir.\n\n"
        "4. Zorunlu arabuluculuk başvurusu yapılmış, [tarih] tarihli son tutanakla taraflar "
        "arasında anlaşma sağlanamamıştır (EK-1).\n\n"
        "**HUKUKİ DAYANAK** : 4857 sayılı İş Kanunu m.17, m.32, m.41, m.46, m.53, m.59; "
