def main():
    data = [
        {"category": CATEGORY, "source": SOURCE, "user": u, "assistant": a}
        for (u, a) in PAIRS
    ]
    OUT_FILE.write_text(
        json.dumps(data, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    print(f"{len(data)} cift yazildi -> {OUT_FILE}")


if __name__ == "__main__":
    main()
